from pathlib import Path
import h5py
import numpy as np

files = sorted([f for f in Path('data').rglob('*') if f.is_file() and f.suffix.lower()=='.nwb'])
print('N_NWB_FILES', len(files))
for f in files:
    print('\n====', f, '====')
    with h5py.File(f, 'r') as h:
        for key in ['identifier', 'session_description', 'general/subject/subject_id']:
            if key in h:
                try:
                    val = h[key][()]
                    if isinstance(val, bytes):
                        val = val.decode()
                    print(key, val)
                except Exception as e:
                    print(key, 'ERR', e)
        print('ophys keys:', list(h['processing/ophys'].keys()) if 'processing/ophys' in h else 'NONE')
        if 'processing/ophys' in h:
            def walk(name, obj):
                if name.startswith('processing/ophys') and (('data' in name) or ('roi' in name.lower()) or ('fluor' in name.lower()) or ('dff' in name.lower()) or ('plane' in name.lower())):
                    typ = 'DATASET' if isinstance(obj, h5py.Dataset) else 'GROUP'
                    shape = getattr(obj, 'shape', '')
                    dtype = getattr(obj, 'dtype', '')
                    print(typ, name, shape, dtype)
            h.visititems(walk)
